/**
 * Market Screener page — full-page view of the real screener panel.
 * Route: /screener
 *
 * Previously this page rendered a fully fabricated table: a hard-coded
 * list of tickers/prices with RSI, MACD, beta, 52-week ranges and other
 * fields generated by Math.random(), and it made zero API calls.
 *
 * It now renders components/panels/MarketScreener, which reads
 * GET /api/market/screener — Alpaca IEX snapshots for the tracked stock
 * universe plus the CoinGecko top 20, via dashboardMarketEvidence.
 * Fields the providers do not supply (RSI, volume ratio, sector, signal)
 * are reported as unavailable by that endpoint and shown as such by the
 * panel — they are never invented here.
 */
import MarketScreener from '../components/panels/MarketScreener';

export default function ScreenerPage() {
  return (
    <div style={{ padding: '24px', maxWidth: 1400, margin: '0 auto' }}>
      <div style={{ marginBottom: 16 }}>
        <h1 style={{ margin: 0, fontSize: 22, fontWeight: 700 }}>Market Screener</h1>
        <p style={{ margin: '4px 0 0', color: 'var(--muted, #64748b)', fontSize: 13 }}>
          Live observations for the tracked universe only — not an exchange-wide ranking.
          Measurements a provider does not supply are shown as unavailable, never estimated.
        </p>
      </div>
      <MarketScreener />
    </div>
  );
}
